export type FeatureTranslationKey = keyof typeof entries;

function dictionary(index: 0 | 1 | 2 | 3 | 4): Record<FeatureTranslationKey, string> {
    return Object.fromEntries(
        Object.entries(entries).map(([key, values]) => [key, values[index]])
    ) as Record<FeatureTranslationKey, string>;
}

